const PARCEL_BOARD={entries:[],lookup:[[],[],[],[],[],[],[],[],[],[],[]],builds:0};
function pbPrism(points,z,Z,ink){const N=points.length,c=[0,0];for(const p of points){c[0]+=p[0]/N;c[1]+=p[1]/N;}for(let n=0;n<N;n++){const a=points[n],b=points[(n+1)%N];pgQuad([c[0],c[1],Z],[a[0],a[1],Z],[b[0],b[1],Z],[c[0],c[1],Z],ink,F_TOP);pgQuad([a[0],a[1],z],[b[0],b[1],z],[b[0],b[1],Z],[a[0],a[1],Z],pgShade(ink,.76+(n%3)*.035),F_Y);}}
function pbArrow(angle,start,head,end,width,shaft,z,ink){const cs=Math.cos(angle),sn=Math.sin(angle),q=[[start,-shaft],[head,-shaft],[head,-width],[end,0],[head,width],[head,shaft],[start,shaft]],p=q.map(a=>[a[0]*cs-a[1]*sn,a[0]*sn+a[1]*cs]);
 // A concave arrow is split at the head so its shoulders remain clean.
 pbPrism([p[0],p[1],p[5],p[6]],z,z+.17,ink);pbPrism([p[2],p[3],p[4]],z,z+.17,ink);
}
