 if(CP.parcel&&CP.mode==='growth'){const m=PC.motion;o.kind='pallet';paArm(o.left,a,side,m.x+1,m.y-7.5,11);paArm(o.right,a,-side,m.x+3.8,m.y-7.5,11);}
 else if(a.action==='push'||a.action==='carry-walk'&&p.place!=='hand'&&!a.grip){const c=PARCELIFE.dispatch;o.kind='push';paArm(o.left,a,side,c.x-2,c.y+8,10);paArm(o.right,a,-side,c.x+4,c.y+8,10);}
