function paDrawArm(h,s){paLimb(h.sx,h.sy,h.sz,h.ex,h.ey,h.ez,3.1,s);paLimb(h.ex,h.ey,h.ez,h.wx,h.wy,h.wz,2.7,s);}
function paSample(p,S){return Math.floor(p/S)+(paperSampleOffset(p%S,S)+.5)/4;}
function parcelActorForward(s){if(s.kind!==0||!PARCEL_ACTORS.ready||!parcelRichOn())return false;const d=PARCEL_ACTORS;if(s.parcelPM){const p=PARCELIFE.pm,key=(p.state===CS_SLEEP?'curl':p.state===CS_STRETCH?'stretch':'watch-'+p.head)+'-'+(p.flick?1:0);paDrawImage(d.pm[key],p.x,p.y,p.z,p.face===1,s);return true;}if(!s.parcelWorker)return false;const o=parcelActorPose(),a=PARCELIFE.sorter;d.slot=s;paDrawArm(o.right,s);paDrawImage(d.bodies[(o.back*5+o.walk+1)*3+o.bend],a.x,a.y,a.z,o.mirror,s);paDrawArm(o.left,s);d.seen=true;d.draws++;return true;}
