// A fixed paper stage, prepared once. Only empty/source-sky depth can sample it.
const PARCEL_BACKDROP={rgb:null,x:0,y:0,w:0,h:0,scale:2,clouds:[],buildings:[],builds:0};
function pbgPaper(x,y){const t=PARCEL_FIDELITY.assets['shared-sky'];if(!t)return 0xffc1b59f;const X=((Math.floor((Math.floor(x*2)+.5)*1.5)%t.width)+t.width)%t.width,q=((Math.floor((Math.floor(y*2)+.5)*1.5)%48)+48)%48,Y=q<24?q:47-q,k=(Y*t.width+X)*4;return(0xff000000|Math.round(t.rgba[k]*.8+39)|Math.round(t.rgba[k+1]*.82+35)<<8|Math.round(t.rgba[k+2]*.86+26)<<16)>>>0;}
function pbgPolygon(ctx,p,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(let n=1;n<p.length;n++)ctx.lineTo(p[n][0],p[n][1]);ctx.closePath();ctx.fill();}
