async function parcelLoadTexture(id,src,m){const im=new Image();im.src=src;await api.decode(im);const c=document.createElement('canvas');c.width=m.width;c.height=m.height;const ctx=c.getContext('2d');ctx.drawImage(im,0,0);return{id,width:c.width,height:c.height,rgba:ctx.getImageData(0,0,c.width,c.height).data,...(m.role==='actor-component'?{canvas:c}:{})};}
function parcelOwnResources(){}

function parcelFidelityReport(){const d=PARCEL_FIDELITY;return{build:BUILD_ID,ready:d.ready,campaign:PARCEL_PROFILE.campaign,builds:d.builds,frames:d.frames,hits:d.hits,resources:d.stages.report(),cacheCount:d.pool.size,spriteCount:d.sprites.size,loadMs:d.loadMs};}
function parcelRegisteredTexture(r,a){const pixels=new Uint8Array(r.pixels.length);for(let k=0;k<pixels.length;k++)pixels[k]=a.rgba[k*4+3]>=3?(r.pixels[k]===EMPTY?C.CREAM:r.pixels[k]):EMPTY;return {...r,pixels,rgba:a.rgba,width:a.width,height:a.height};}
async function parcelFidelityBoot(){const d=PARCEL_FIDELITY;

 for(const[id,item]of Object.entries(PARCEL_ASSETS))d.assets[id]=await parcelLoadTexture(id,item.src,item);api.check();
 for(const[hash,r]of paperLookup){const a=d.assets[r.id];if(a&&a.width===r.w*4&&a.height===r.h*4)d.sprites.set(r.id,parcelRegisteredTexture(r,a));}
 for(const list of paperPieceLookup)if(list)for(const r of list){if(!r)continue;const a=d.assets[r.id];if(a&&a.width===r.w*4&&a.height===r.h*4)d.sprites.set(r.id,parcelRegisteredTexture(r,a));}
 d.world=new Uint32Array(WN*16);d.worldRef=new Uint8Array(WN*16);d.worldDep=new Int16Array(WN*16);d.scratch=new Uint32Array(WN*16);d.scratchRef=new Uint8Array(WN*16);d.capture=true;
 parcelInstallCapture();ROOMS.parcel.activate=activateParcel;if(typeof parcelGeometryInstall==='function')parcelGeometryInstall();if(typeof parcelActorInstall==='function')parcelActorInstall();parcelStudySelect('7-15');pcPrepareTruck();
 if(typeof parcelBackdropPrepare==='function')parcelBackdropPrepare();
 if(typeof parcelGeometryPrepare==='function')await parcelGeometryPrepare();api.check();
 if(typeof parcelActorPrepare==='function')await parcelActorPrepare();api.check();
 if(typeof parcelBoardPrepare==='function')await parcelBoardPrepare();api.check();
 d.locked=true;d.scratch=d.scratchRef=null;d.stages=makeFidelityFramework();parcelOwnResources();d.stages.seal();d.builds++;d.ready=true;d.loadMs=performance.now()-d.started;gMeasureHud();gCamera();dirty=true;
}

const webHooks={colour:(dst,r,x,y,l,b)=>parcelBlend(dst,parcelSpriteColour(r,x,y,l,b),r.rgba[(y*r.width+x)*4+3]),
  beforeCache:()=>PARCEL_FIDELITY.counts.clear(),materials:parcelFrameMaterials,staticColour:parcelStaticColour,propColour:parcelPropColour,
  skip:s=>parcelBoardForward(s)||parcelActorForward(s),finishBeforeCues:parcelActorFinish,finishAfterCues:parcelFinalColour};
api.hooks(webHooks);
let webMounted=false;
return {async mount(){api.check();await parcelFidelityBoot();api.check();webMounted=true;},
 async refresh(){api.check();api.rebake();api.check();},
 dispose(){webMounted=false;},resources(){if(!webMounted)return {bytes:0,buffers:0};return api.resources([PARCEL_FIDELITY,PARCEL_GEOMETRY,PARCEL_ACTORS,PARCEL_BOARD,PARCEL_BACKDROP]);}};
